import { v4 as uuidv4 } from 'uuid';
import {
  Artifact,
  CreateArtifactRequest,
  UpdateArtifactRequest,
} from '../types';
import { extractVariables } from '../utils/template-engine';
import { FileStorage } from '../utils/file-utils';
import config from '../config';

export class ArtifactService {
  private storage: FileStorage;

  constructor(storagePath?: string) {
    this.storage = new FileStorage(storagePath || config.storagePath);
  }

  async create(request: CreateArtifactRequest): Promise<Artifact> {
    const now = new Date().toISOString();
    const variables = extractVariables(request.content);

    const artifact: Artifact = {
      id: uuidv4(),
      name: request.name,
      content: request.content,
      metadata: {
        version: 1,
        ...request.metadata,
      },
      variables,
      createdAt: now,
      updatedAt: now,
    };

    await this.storage.save(artifact);
    return artifact;
  }

  async findById(id: string): Promise<Artifact | null> {
    return this.storage.findById(id);
  }

  async findAll(): Promise<Artifact[]> {
    return this.storage.findAll();
  }

  async update(
    id: string,
    request: UpdateArtifactRequest
  ): Promise<Artifact | null> {
    const existing = await this.storage.findById(id);
    if (!existing) {
      return null;
    }

    const now = new Date().toISOString();
    const content = request.content ?? existing.content;
    const variables = extractVariables(content);

    const updated: Artifact = {
      ...existing,
      name: request.name ?? existing.name,
      content,
      metadata: {
        ...existing.metadata,
        ...request.metadata,
        version: (existing.metadata.version || 0) + 1,
      },
      variables,
      updatedAt: now,
    };

    await this.storage.save(updated);
    return updated;
  }

  async delete(id: string): Promise<boolean> {
    return this.storage.delete(id);
  }

  async render(
    id: string,
    variables: Record<string, string>
  ): Promise<{ rendered: string; original: string; variablesUsed: string[] } | null> {
    const artifact = await this.storage.findById(id);
    if (!artifact) {
      return null;
    }

    const variablesUsed: string[] = [];
    let rendered = artifact.content;

    for (const [key, value] of Object.entries(variables)) {
      const pattern = new RegExp(`\\{\\{\\s*${key}\\s*\\}\\}`, 'g');
      if (pattern.test(rendered)) {
        variablesUsed.push(key);
        rendered = rendered.replace(pattern, value);
      }
    }

    return {
      rendered,
      original: artifact.content,
      variablesUsed,
    };
  }
}

export const artifactService = new ArtifactService();
